/***/ "./resources/js/components/non_muslim_data/keyInsights.json":
/*!******************************************************************!*\
  !*** ./resources/js/components/non_muslim_data/keyInsights.json ***!
  \******************************************************************/
/***/ ((module) => {

module.exports = /*#__PURE__*/JSON.parse('[{"chapterId":1,"chapter":"One God","keyInsights":["Tawheed frames every action when you name Allah, you are anchoring your entire day.","Seeing Allah’s unity in creation softens fear and keeps reliance steady.","Simple acts of remembrance keep the Shahada present even during hectic moments.","Sharing what you learn about Allah cements it in your heart.","Gratitude-based dhikr turns ordinary life into continuous testimony."]},{"chapterId":2,"chapter":"The Qur\'an","keyInsights":["The Qur’an is a living conversation that changes when you engage slowly.","Every verse contains threads that tie into your current reality if you pause to see them.","Listening to recitation reminds you that sound and silence both honor the text.","Questions lead to deeper trust; don’t shy away from them, bring them to a teacher.","Consistent reflection beats dramatic leaps in mastery."]},{"chapterId":3,"chapter":"The Prophet","keyInsights":["Mercy was his default response even when others resisted.","His character shows how Tawheed moves from belief to behavior.","Studying him inspires practical habits more than lofty ideals.","Patience and humility were strategies, not traits you’re born with.","Imitating small Sunnah details builds lasting resilience."]},{"chapterId":4,"chapter":"Main Practices","keyInsights":["The five pillars work like a spiritual skeleton each part supports the whole.","Consistent tiny rituals beat sporadic, grand gestures.","Intentional planning keeps the pillars from becoming just chores.","Seeing service as part of worship makes discipline joyful.","When understanding outpaces perfection, you stay motivated."]},{"chapterId":5,"chapter":"Prayer","keyInsights":["Salah creates sacred pauses that recalibrate anxiety into submission.","Presence matters more than perfection focus beats flawless recitation.","Knowing the meaning of what you say fuels devotion.","Duas after prayer turn routine into dialogue.","Congregational prayer multiplies the calm you harvest."]},{"chapterId":6,"chapter":"Ramadan","keyInsights":["Fasting unfolds empathy by shrinking the focus on self.","Daily pairing of restraint with generosity deepens gratitude.","Night worship renews what daytime fasting works to train.","Sharing iftar and duaas builds communal strength.","A single charitable act during the fast can start a lifelong habit."]},{"chapterId":7,"chapter":"Good Character","keyInsights":["Kind speech heals faster than harsh correction.","Adab is worship when consistency shapes interactions.","Modeling humility invites others to mirror it.","Forgiveness resets wounded hearts and keeps relationships alive.","When praise is sincere, it becomes a gentle da\'wah."]},{"chapterId":8,"chapter":"Peace & Respect","keyInsights":["Peace begins with curiosity, not with proving someone wrong.","Respectful listening is a form of worship.","Small acts of courtesy revive trust in fractured relationships.","Diversity becomes a strength when everyone feels heard.","Praying for peace anchors your outward gestures in intention."]},{"chapterId":9,"chapter":"The Prophets","keyInsights":["Every prophet carried the same core message consistency matters more than flair.","Their resilience encourages you to keep showing up even after setbacks.","Choosing one prophetic story a week keeps the legacy alive.","Their patience model tells you to pair hope with effort.","Reflecting on their tests connects your struggles to a larger narrative."]},{"chapterId":10,"chapter":"The Mosque","keyInsights":["Mosques are more than buildings; they are shelters for your soul.","Showing up even quietly signals devotion and belonging.","Helping maintain the space ties you to the community physically and spiritually.","Listening to sermons with a notebook makes the lessons stick.","Praying with others trains humility and offers accountability."]},{"chapterId":11,"chapter":"Halal Life","keyInsights":["Halal is integrity across food, finance, and relationships.","Transparent choices earn trust more than polished claims.","Resting well keeps your heart aligned with halal intentions.","Regular honesty strengthens character even when it costs comfort.","Small ethical adjustments ripple into community-wide trust."]},{"chapterId":12,"chapter":"Men & Women","keyInsights":["Mutual respect is at the heart of Islamic balance.","Boundaries protect dignity while encouraging compassion.","Cooperation between genders demonstrates Prophetic mercy.","Teaching young people respect anchors future relationships.","Prayer for equity reinforces emotional sensitivity."]},{"chapterId":13,"chapter":"Becoming Muslim","keyInsights":["The shahada is both declaration and direction.","Community care smooths the transition from curiosity to conviction.","Asking questions keeps the journey authentic.","Celebrating milestones honors the courage it took to begin.","Supportive mentors turn uncertainty into steady progress."]},{"chapterId":14,"chapter":"Eid Festivals","keyInsights":["Gratitude turns Eid into a spiritual recharge instead of a spectacle.","Giving to others keeps celebration grounded in compassion.","Remembering prophets’ Eids deepens your joy with purpose.","Combining prayer with festive traditions balances devotion and delight.","Inviting others especially those alone perfects the celebration."]},{"chapterId":15,"chapter":"Afterlife","keyInsights":["Each deed builds a bridge to the everlasting.","Repentance is swift course correction before the scales tip.","Charity invests in rewards you cannot see yet.","Balancing hope with accountability keeps the heart steady.","Praying for mercy anchors every aging moment in gratitude."]}]');

/***/ }),

